let ottoSeq = 0;
function otto(estado, classe = "", animado = true) {
  let h = OTTO_DESENHOS[estado].split("__ID__").join("otto" + ++ottoSeq).replace("__CLASSE__", classe);
  if (!animado) h = h.replace("otto-vivo ", "");
  return h;
}
function ottoMini(estado, classe = "") {
  return OTTO_MINIS[estado].replace("__CLASSE__", classe);
}
